	@Test
	void closesLeftIterationWhenCancellationRacesItsLateInitialization() throws Exception {
		CountDownLatch rightCloseEntered = new CountDownLatch(1);
		CountDownLatch allowRightClose = new CountDownLatch(1);
		CountDownLatch allowLeftHasNext = new CountDownLatch(1);
		AtomicBoolean leftOpened = new AtomicBoolean();
		AtomicReference<Throwable> evaluationFailure = new AtomicReference<>();

		TrackingIteration leftIteration = new TrackingIteration(allowLeftHasNext);
		CloseableIteration<BindingSet> rightIteration = new CloseableIteration<>() {
			private final AtomicBoolean rowAvailable = new AtomicBoolean(true);
			private final AtomicBoolean closeStarted = new AtomicBoolean();

			@Override
			public boolean hasNext() {
				return rowAvailable.get();
			}

			@Override
			public BindingSet next() {
				rowAvailable.set(false);
				QueryBindingSet row = new QueryBindingSet();
				row.addBinding("join", SimpleValueFactory.getInstance().createLiteral("right"));
				return row;
			}

			@Override
			public void close() {
				if (closeStarted.compareAndSet(false, true)) {
					rightCloseEntered.countDown();
					await(allowRightClose);
				}
			}
		};

		QueryEvaluationStep left = ignored -> {
			leftOpened.set(true);
			return leftIteration;
		};
		QueryEvaluationStep right = ignored -> rightIteration;
		MaterializedReplayJoinIterator iterator = new MaterializedReplayJoinIterator(left, right, null,
				EmptyBindingSet.getInstance(), false, Set.of(), new String[] { "join" });

		Thread evaluationThread = new Thread(() -> {
			try {
				iterator.hasNext();
			} catch (Throwable t) {
				evaluationFailure.set(t);
			}
		}, "MaterializedReplayJoinIteratorTest");
		evaluationThread.start();

		try {
			assertTrue(rightCloseEntered.await(5, TimeUnit.SECONDS), "right cleanup did not start");
			iterator.close();
			allowRightClose.countDown();
			allowLeftHasNext.countDown();
			evaluationThread.join(TimeUnit.SECONDS.toMillis(5));

			assertFalse(evaluationThread.isAlive(), "evaluation did not stop");
			assertNull(evaluationFailure.get());
			if (leftOpened.get()) {
				assertEquals(1, leftIteration.closeCount.get(),
						"a left iteration opened after cancellation must be closed exactly once");
			}
		} finally {
			allowRightClose.countDown();
			allowLeftHasNext.countDown();
			iterator.close();
			evaluationThread.join(TimeUnit.SECONDS.toMillis(5));
		}
	}

