	private static void await(CountDownLatch latch) {
		try {
			if (!latch.await(5, TimeUnit.SECONDS)) {
				throw new AssertionError("timed out waiting for test coordination");
			}
		} catch (InterruptedException e) {
			Thread.currentThread().interrupt();
			throw new AssertionError(e);
		}
	}

	private static final class TrackingIteration implements CloseableIteration<BindingSet> {

		private final CountDownLatch allowHasNext;
		private final AtomicInteger closeCount = new AtomicInteger();

		private TrackingIteration(CountDownLatch allowHasNext) {
			this.allowHasNext = allowHasNext;
		}

		@Override
		public boolean hasNext() {
			await(allowHasNext);
			return false;
		}

		@Override
		public BindingSet next() throws QueryEvaluationException {
			throw new QueryEvaluationException("no left rows");
		}

		@Override
		public void close() {
			closeCount.incrementAndGet();
		}
	}
